data class PlanDto(@Json(name="plan_code") val planCode:String,@Json(name="plan_name") val planName:String,val status:String,@Json(name="storage_quota_bytes") val storageQuotaBytes:Long,@Json(name="max_attachment_bytes") val maxAttachmentBytes:Long,@Json(name="attachment_retention_seconds") val attachmentRetentionSeconds:Long,@Json(name="max_devices") val maxDevices:Int,@Json(name="premium_url") val premiumUrl:String?)
data class UsageDto(@Json(name="storage_verified_bytes") val storageVerifiedBytes:Long,@Json(name="storage_pending_bytes") val storagePendingBytes:Long,@Json(name="storage_quota_bytes") val storageQuotaBytes:Long,@Json(name="storage_used_percent") val storageUsedPercent:Double,@Json(name="uploads_today_bytes") val uploadsTodayBytes:Long,@Json(name="uploads_today_count") val uploadsTodayCount:Int)
data class SupportConfigDto(@Json(name="support_enabled") val supportEnabled:Boolean,@Json(name="donations_enabled") val donationsEnabled:Boolean,@Json(name="donation_url_fr") val donationUrlFr:String?,@Json(name="donation_url_en") val donationUrlEn:String?,@Json(name="donation_url_default") val donationUrlDefault:String?,@Json(name="premium_enabled") val premiumEnabled:Boolean,@Json(name="premium_url_fr") val premiumUrlFr:String?,@Json(name="premium_url_en") val premiumUrlEn:String?,@Json(name="premium_url_default") val premiumUrlDefault:String?){fun donationUrl(language:String)=when(language){"fr"->donationUrlFr?:donationUrlDefault;"en"->donationUrlEn?:donationUrlDefault;else->donationUrlDefault};fun premiumUrl(language:String)=when(language){"fr"->premiumUrlFr?:premiumUrlDefault;"en"->premiumUrlEn?:premiumUrlDefault;else->premiumUrlDefault}}
